def solution(s):
    n, x = map(int, s.split())

    # For the problem of finding rotatable number:
    # Key insight: b^n ≡ 1 (mod p) with order exactly n for some prime p ≡ 1 (mod n)
    # This typically means n | (b-1) and b^n-1 has appropriate prime factors

    if n == 1:
        return str(max(2, x - 1)) + '\n' if x > 2 else '-1\n'

    for b in range(x - 1, 2, -1):
        if (b - 1) % n != 0:
            continue

        bn1 = pow(b, n) - 1

        # Check if there exists prime p | (b^n-1) with p ≡ 1 (mod n) and proper order
        p = find_prime_factor(bn1, n)
        if p is not None and check_order(b, p, n):
            return str(b) + '\n'

    return '-1\n'

def find_prime_factor(val, n):
    d = 2
    while d * d <= val:
        if val % d == 0:
            if d % n == 1 and is_prime(d):
                return d
            while val % d == 0:
                val //= d
        d += 1
    if val > 1 and val % n == 1:
        return val
    return None

def is_prime(p):
    if p < 2:
        return False
    if p == 2:
        return True
    if p % 2 == 0:
        return False
    for i in range(3, int(p**0.5) + 1, 2):
        if p % i == 0:
            return False
    return True

def check_order(b, p, n):
    if pow(b, n, p) != 1:
        return False
    for k in range(1, n):
        if pow(b, k, p) == 1:
            return False
    return True
