def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m, k = map(int, lines[0].split())

    if n == 1:
        return "0\n\n"

    edges = []
    capital_edges = []

    for i in range(1, m + 1):
        parts = lines[i].split()
        a, b, w = int(parts[0]), int(parts[1]), int(parts[2])
        edges.append((w, a, b, i))
        if a == 1 or b == 1:
            capital_edges.append((w, a, b, i))

    if k > len(capital_edges):
        return "-1\n"

    parent = list(range(n + 1))
    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]
    def union(x, y):
        rx, ry = find(x), find(y)
        if rx != ry:
            parent[rx] = ry
            return True
        return False

    result = []

    # Select k capital edges (cheapest ones that connect new nodes)
    capital_by_weight = sorted(capital_edges, key=lambda x: x[0])

    capital_selected = set()
    for w, a, b, idx in capital_by_weight:
        if len([i for i in capital_selected]) < k:
            if union(a, b):
                capital_selected.add(idx)
                result.append(idx)

    # Now add more edges to complete spanning tree, skip needed capital edges
    for w, a, b, idx in sorted(edges, key=lambda x: x[0]):
        if idx in capital_selected:
            # Already added this capital edge
            continue
        if union(a, b):
            result.append(idx)

    # Check connectivity
    roots = set(find(i) for i in range(1, n + 1))
    if len(roots) != 1:
        return "-1\n"

    # Check capital edge count
    capital_in_result = sum(1 for idx in result if idx in capital_selected)
    if capital_in_result != k:
        return "-1\n"

    result.sort()
    return f"{len(result)}\n{' '.join(map(str, result))}\n"
