```python
# Final solution
#!/usr/bin/env python3
import sys

MOD = 1000000007

def mat_vec_mul(T, v, M):
    """Multiply matrix T (M x M) by vector v of length M."""
    return [(sum(T[i][j] * v[j] for j in range(M)) % MOD) for i in range(M)]

def mat_mul(A, B, M):
    """Multiply two M x M matrices."""
    C = [[0] * M for _ in range(M)]
    for i in range(M):
        for k in range(M):
            if A[i][k]:
                for j in range(M):
                    if B[k][j]:
                        C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % MOD
    return C

def mat_pow(T, n, M):
    """Raise matrix T to power n using binary exponentiation."""
    result = [[0] * M for _ in range(M)]
    for i in range(M):
        result[i][i] = 1
    base = [row[:] for row in T]
    while n > 0:
        if n & 1:
            result = mat_mul(result, base, M)
        base = mat_mul(base, base, M)
        n >>= 1
    return result

def solution(input_str):
    lines = input_str.strip().split('\n')
    F, B, N = map(int, lines[0].split())
    petals = list(map(int, lines[1].split()))
    chocolates = list(map(int, lines[2].split()))

    M = 5000

    # Flower matrix: T[k][i] = 1 if i == k or k - i = pj for some j
    T = [[0] * M for _ in range(M)]
    for k in range(M):
        T[k][k] = 1
        for pj in petals:
            if k >= pj:
                T[k][k - pj] = 1

    # Initial polynomial: 1 (represented as [1, 0, 0, ...])
    coeffs = [0] * M
    coeffs[0] = 1

    # Compute T^N * initial vector
    T_N = mat_pow(T, N, M)
    for i in range(M):
        coeffs[i] = (coeffs[i] + T_N[i][0]) % MOD

    # Box coefficients: DP
    box_coeffs = [0] * M
    box_coeffs[0] = 1
    for i in range(1, M):
        for cj in chocolates:
            if i >= cj:
                box_coeffs[i] = (box_coeffs[i] + box_coeffs[i - cj]) % MOD

    # Answer: sum of A[S] * B[S]
    ans = sum((coeffs[i] * box_coeffs[i]) % MOD for i in range(M)) % MOD
    return str(ans) + '\n'
