            while self.pos < len(self.s) and self.s[self.pos].isdigit():
                self.pos += 1
            num_str = self.s[start:self.pos]
            num = int(num_str)

            if self.pos < len(self.s) and self.s[self.pos] == '-':
                self.pos += 1
                start_r = self.pos
                while self.pos < len(self.s) and self.s[self.pos].isdigit():
                    self.pos += 1
                r_num = int(self.s[start_r:self.pos])
                return mod_concat_numbers(num, r_num)

            if self.pos < len(self.s) and self.s[self.pos] == '(':
                self.pos += 1
                inner = self.parse_expression()
                if self.pos < len(self.s) and self.s[self.pos] == ')':
                    self.pos += 1
                return repeat_expr(num, inner)

            return mod_concat_numbers(num, num)

    def digit_count(n):
        return len(str(n))

    def mod_pow(base, exp, mod):
        return pow(base, exp, mod)

    def mod_concat_numbers(a, b):
        """Concatenate a and b, returning the result modulo MOD"""
        if a > b:
            return 0
        result = 0
        for i in range(a, b + 1):
            s = str(i)
            result = (result * mod_pow(10, len(s), MOD) + i) % MOD
        return result

    def repeat_expr(n, expr):
        """Repeat the expression n times and return the result modulo MOD"""
        if n == 0:
            return 0
        expr_result = expr
        total_len = 0
        MOD = 10**9 + 7

        # Calculate the length of the expression string representation
        s_expr = str(expr_result)
        len_expr = len(s_expr)

        result = 0
        for _ in range(n):
            result = (result * mod_pow(10, len_expr, MOD) + expr_result) % MOD

        return result

    result = Parser(s).parse_expression()
    return str(result % MOD) + "\n"
