    # We'll use at most 4 different points since n <= 8
    for k in range(1, 5):  # At most 4 positions
        if k > n:
            continue

        # Choose k points (need at least k points available)
        if len(pts) < k:
            continue

        # For each combination of k points
        for combo in itertools.combinations(pts, k):
            # Try all distributions of n towers into these k positions
            # Use recursion or dynamic programming
            from collections import Counter

            def find_split(pos_idx, remaining, counter):
                nonlocal ans, best
                if pos_idx == k:
                    if remaining == 0:
                        # Calculate sum of squared distances for this assignment
                        total = 0
                        positions = []
                        for (px, py), count in counter.items():
                            for _ in range(count):
                                positions.append((px, py))

                        # Sum over all pairs
                        for i in range(len(positions)):
                            for j in range(i+1, len(positions)):
                                d2 = (positions[i][0] - positions[j][0])**2 + (positions[i][1] - positions[j][1])**2
                                total += d2

