                    for count in range(min(remaining, 8)):  # Max 8 towers at one position
                        if count > n - pos_idx * (remaining // k):  # Optimization
                            break
                        if count <= 0:
                            continue
                        counter[(x, y)] = count

                        find_split(pos_idx + 1, remaining - count, counter)
                        del counter[(x, y)]

            counter = Counter()
            find_split(0, n, counter)

    # Fallback to simple 2-position strategy
    if ans == 0:
        # Use 0 as p1 and a point at boundary as p2
        p1 = (0, 0)
        p2 = (r, 0) if abs(r) > 0 else (1, 1)
        if p2 not in pts:
