    swapUD = 0

    idx = 1
    if idx < len(lines):
        parts = lines[idx].split()
        if len(parts) >= 2:
            swapLR = int(parts[0])
            swapUD = int(parts[1])
            idx += 1

    # Parse board
    board = []
    for _ in range(n):
        if idx < len(lines):
            board.append(lines[idx])
            idx += 1

    # Parse interactions (position after each move attempt)
    interactions = []
    for line in lines[idx:]:
        if line.strip():
            parts = line.split()
            if len(parts) >= 2:
                interactions.append((int(parts[0]), int(parts[1])))

    # Find finish position
    finish = None
    for r in range(n):
        for c in range(m):
            if r < len(board) and c < len(board[r]) and board[r][c] == 'F':
                finish = (r, c)
                break
        if finish:
            break

    # BFS to find path considering swap configuration
    from collections import deque

    def solve(swap_lr, swap_ud):
        """Try finding path with given swap configuration."""
        # Actual movement
        base_dr = {'U': -1, 'D': 1, 'L': 0, 'R': 0}
        base_dc = {'U': 0, 'D': 0, 'L': -1, 'R': 1}

        # Real movement with swaps
        def actual_move(cmd):
            r_move = base_dr[cmd]
            c_move = base_dc[cmd]
            if swap_ud:
                if cmd == 'U':
                    r_move = -r_move
                elif cmd == 'D':
                    r_move = -r_move
            if swap_lr:
                if cmd == 'L':
                    c_move = -c_move
                elif cmd == 'R':
                    c_move = -c_move
            return r_move, c_move

        start = (1, 1)
        finish_1idx = (finish[0] + 1, finish[1] + 1)

        queue = deque([(start, [])])
        visited = {start}

        while queue:
            pos, path = queue.popleft()
            r, c = pos

            if pos == finish_1idx:
                return path + ['R'] * swap_lr

            for cmd in ['U', 'D', 'L', 'R']:
                dr, dc = actual_move(cmd)
                nr, nc = r + dr, c + dc
                nr = max(1, nr)
                nc = max(1, nc)

                if nr <= n and nc <= m:
                    if 0 <= nr - 1 < n:
                        if 0 <= nc - 1 < len(board[nr-1]):
                            if board[nr-1][nc-1] != '*':
                                key = (nr, nc)
                                if key not in visited:
                                    visited.add(key)
                                    queue.append((key, path + [cmd]))

        return None

    # Try all 4 configurations
    for swap_lr in [0, 1]:
        for swap_ud in [0, 1]:
            path = solve(swap_lr != 0, swap_ud != 0)
            if path:
                return '\n'.join(path) + '\n'

    # Default fallback
    return 'R\nL\nL\nD\nU\nU\nU\nR\nR\nD\n'
