def solution(input_str):
    """
    Reads input with n integers and m coupons.
    For a beautiful array with k distinct elements, we need at most k*(k-1) + 1 positions.
    Given n positions, we can use at most ceil(sqrt(2n + 1/4) - 1/2) distinct elements.
    More simply: select min(m, ceil(sqrt(2*n))) coupons with highest weights.
    """
    lines = input_str.strip().split('\n')
    if len(lines) < 1:
        return "0\n"

    n, m = map(int, lines[0].split())

    weights = []
    for i in range(1, min(m + 1, len(lines))):
        parts = list(map(int, lines[i].split()))
        if len(parts) >= 2:
            weights.append(parts[1])  # wi is weight

    if not weights:
        return "0\n"

    weights.sort(reverse=True)

    # Maximum distinct elements we can support
    # Formula: k*(k-1) <= n-1 for n positions
    # Solve: k <= (1 + sqrt(1 + 4*(n-1)))/2
    import math
    max_k = int((1 + math.sqrt(1 + 4 * (n - 1))) / 2)
    if max_k < 2:
        max_k = 1

    k = min(m, max_k)
    if k < 1:
        k = 1

    result = sum(weights[:k])

    return f"{result}\n"

